function findFootprint(comps, fps, des) {
  for (var i = 0; i < comps.length; i++) {
    var c = comps[i];
    if (c.cppname !== des) continue;
    var ids = c.gIds || [];
    for (var j = 0; j < ids.length; j++) { if (fps[ids[j]]) return ids[j]; }
  }
  return null;
}

function main() {
  var src = api('getSource', { type: 'json' });
  var root = src.shape || src;
  var comps = root.component || [];
  var fps = root.FOOTPRINT || root.package || {};
  var missed = [];
  var done = 0;
  for (var k = 0; k < PARTS.length; k++) {
    var p = PARTS[k];
    var id = findFootprint(comps, fps, p[0]);
    if (!id) { missed.push(p[0]); continue; }
    api('moveObjsTo', { objs: [id],
      x: api('coordConvert', { type: 'real2canvas', x: p[1] + 'mil' }),
      y: api('coordConvert', { type: 'real2canvas', y: p[2] + 'mil' }) });
    if (p[3]) api('rotate', { ids: [id], degree: p[3] });
    done++;
  }
  var msg = 'Auto placement done: ' + done + ' / ' + PARTS.length +
            '\nNot found: ' + (missed.length ? missed.join(', ') : 'none');
  if (typeof alert === 'function') { alert(msg); } else { console.log(msg); }
}

main();
